   d.props=list.ToArray();foreach(var mat in colors.Values)if(mat&&mat.shader.name=="Speed Stars/Pastel Street Prop"){mat.shader=Shader.Find("Speed Stars/Desert Pixel Paint");EditorUtility.SetDirty(mat);}EditorUtility.SetDirty(d);AssetDatabase.SaveAssets();System.IO.File.WriteAllText("Docs/MarinePropAudit.md",string.Join("\n",egyptAudit.ToArray()));return list.Count+" dock compositions; anchor, chest and cargo crate removed from active prop pool";
